    auth = "both",
    schemas,
    rateLimit = true,
    customRateLimitConfig,
    bodyLimitBytes = DEFAULT_REQUEST_BODY_LIMIT_BYTES,
    concurrency,
    handler,
    action,
    targetType,
  } = params;

